package com.agroprecision.controller;

import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;

/**
 * Redirects the `/assistant` endpoint to the bundled chatbot UI.
 * The UI files are placed under classpath:/static by the Maven resources plugin.
 */
@Controller
public class AssistantRedirectController {

    @GetMapping("/assistant")
    public String redirectToChatbot() {
        // Forward to the static index.html generated by the chatbot module
        return "forward:/static/index.html";
    }
}

